using MediatR;using Microsoft.AspNetCore.Mvc;using Namaa.Api.Contracts.PurchaseInvoices;using Namaa.Api.Extensions;using Namaa.Application.PurchaseInvoices.Commands.CreatePurchaseInvoice;using Namaa.Application.PurchaseInvoices.Commands.UpdatePurchaseInvoice;using Namaa.Application.PurchaseInvoices.Commands.AddPurchaseInvoiceItem;using Namaa.Application.PurchaseInvoices.Queries.GetPurchaseInvoiceById;using Namaa.Application.PurchaseInvoices.Queries.GetPurchaseInvoices;namespace Namaa.Api.Controllers;[ApiController][Route("api/purchase-invoices")]public sealed class PurchaseInvoicesController(ISender sender):ControllerBase{[HttpPost]public async Task<IActionResult>Create(CreatePurchaseInvoiceRequest request,CancellationToken cancellationToken){var x=await sender.Send(new CreatePurchaseInvoiceCommand(request.SupplierId,request.PurchaseInvoiceNumber,request.IssueDate,request.ProjectId,request.SupplierInvoiceNumber,request.DueDate,request.Notes),cancellationToken);return x.IsFailure?x.ToActionResult(this):CreatedAtAction(nameof(GetById),new{id=x.Value.Id},x.Value);}[HttpGet]public async Task<IActionResult>GetAll(CancellationToken cancellationToken)=>(await sender.Send(new GetPurchaseInvoicesQuery(),cancellationToken)).ToActionResult(this);[HttpGet("{id:long}")]public async Task<IActionResult>GetById(long id,CancellationToken cancellationToken)=>(await sender.Send(new GetPurchaseInvoiceByIdQuery(id),cancellationToken)).ToActionResult(this);[HttpPut("{id:long}")]public async Task<IActionResult>Update(long id,UpdatePurchaseInvoiceRequest request,CancellationToken cancellationToken)=>(await sender.Send(new UpdatePurchaseInvoiceCommand(id,request.IssueDate,request.DueDate,request.SupplierInvoiceNumber,request.Notes,request.RowVersion),cancellationToken)).ToActionResult(this);[HttpPost("{id:long}/items")]public async Task<IActionResult>AddItem(long id,AddPurchaseInvoiceItemRequest request,CancellationToken cancellationToken)=>(await sender.Send(new AddPurchaseInvoiceItemCommand(id,request.Description,request.Quantity,request.UnitPrice,request.DiscountAmount,request.TaxAmount,request.LineTotal,request.RowVersion),cancellationToken)).ToActionResult(this);}
